import { lessons, modules } from './course.js';
import { ROLES, watchAuth, signUp, signIn, signOutStudent, resetPassword, loadStudent, createStudent, saveStudent } from './firebase.js';
const $ = (s, root = document) => root.querySelector(s);
const icon = (name, cls='') => `<svg class="icon ${cls}" viewBox="0 0 256 256" fill="currentColor" aria-hidden="true">${phosphorIcons[name] || phosphorIcons.code}</svg>`;
const escape = s => String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const defaultState = {name:'',project:'My first app',idea:'',done:[],checks:{},notes:{},last:1,started:false};
let state;
try { const raw=JSON.parse(localStorage.getItem('codeclass-v1') || '{}'); state={...defaultState,...raw}; state.done=Array.isArray(raw.done)?raw.done.filter(id=>lessons.some(l=>l.id===id)):[]; for(const key of ['checks','notes']) if(!state[key]||typeof state[key]!=='object'||Array.isArray(state[key])) state[key]={}; for(const key of ['name','project','idea']) if(typeof state[key]!=='string') state[key]=defaultState[key]; } catch {state=structuredClone(defaultState);}
let storageWarned=false;
function writeLocal(){try{localStorage.setItem('codeclass-v1',JSON.stringify(state));}catch{if(!storageWarned){toast('Storage is unavailable. Your progress will last for this session.');storageWarned=true;}}}
function save(){writeLocal();queueSync();}
let authUser=null,student=null,authReady=false,authFlow=false,pendingAction=null,syncTimer=null,syncWarned=false,resolveAuthReady;
const authReadyPromise=new Promise(resolve=>{resolveAuthReady=resolve;});
function remoteData(){const checks={};for(const [id,list] of Object.entries(state.checks))if(Array.isArray(list))checks[id]=Array.from(list,Boolean);return {name:state.name,role:student?.role,project:{name:state.project,idea:state.idea},progress:{completedLessons:[...state.done].sort((a,b)=>a-b),completedCount:state.done.length,totalLessons:lessons.length,percent:percent(),currentStep:currentStep()+1,currentStepTitle:modules[currentStep()].title,lastLessonId:state.last,started:state.started,completedAt:state.completedAt||null,checks},notes:{...state.notes}};}
function applyRemote(data){const p=data.progress||{},isMap=v=>v&&typeof v==='object'&&!Array.isArray(v);state={...structuredClone(defaultState),name:typeof data.name==='string'?data.name:'',project:typeof data.project?.name==='string'?data.project.name:defaultState.project,idea:typeof data.project?.idea==='string'?data.project.idea:'',done:Array.isArray(p.completedLessons)?p.completedLessons.filter(id=>lessons.some(l=>l.id===id)):[],checks:isMap(p.checks)?p.checks:{},notes:isMap(data.notes)?data.notes:{},last:Number(p.lastLessonId)||1,started:Boolean(p.started)};if(p.completedAt)state.completedAt=p.completedAt;writeLocal();}
function queueSync(){if(!student)return;clearTimeout(syncTimer);syncTimer=setTimeout(syncNow,800);}
async function syncNow(){clearTimeout(syncTimer);syncTimer=null;if(!student)return;try{await saveStudent(student.uid,remoteData());}catch(err){console.error(err);if(!syncWarned){toast('We couldn’t save to your account. Your progress is still saved in this browser.');syncWarned=true;}}}
const percent=()=>Math.round(state.done.length/lessons.length*100);
const nextLesson=()=>lessons.find(l=>!state.done.includes(l.id))||lessons[11];
const currentStep=()=>{const i=modules.findIndex(m=>!m.lessons.every(id=>state.done.includes(id)));return i<0?modules.length-1:i;};
let page='overview',filter='all',toastTimer;
function toast(message){const target=$('#modal').open?$('#modal'):document.body;target.append($('#toast'));$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3200);}
function hydrate(){document.querySelectorAll('[data-icon]').forEach(el=>{el.innerHTML=icon(el.dataset.icon);});}
function profileUI(){const initial=(state.name.trim()[0]||'Y').toUpperCase();$('#profile-name').textContent=state.name||'Your workspace';$('#profile-role').textContent=student?student.role:authReady?'Sign up to save progress':'Future app builder';$('#avatar').textContent=initial;$('#top-avatar').textContent=initial;$('#sidebar-project-name').textContent=state.project||'My first app';}
const pageHead=(eyebrow,title,subtitle,action='')=>`<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${subtitle}</p></div>${action}</div>`;
const toolLogo=(tool)=> tool==='Cursor'?`<span class="tool-logo cursor-logo">◩</span>`:tool==='Expo'?`<span class="tool-logo expo-logo">Λ</span>`:tool==='Firebase'?`<span class="tool-logo firebase-logo">${icon('bolt')}</span>`:`<span class="tool-logo github-logo">${icon('github')}</span>`;
const toolkit=()=>`<section class="card toolkit"><div class="section-title"><h2>Your builder’s toolkit</h2>${icon('layers')}</div><p>A few great tools. So many possibilities.</p>${[['Cursor','Your AI coding partner','https://cursor.com/'],['Expo','One app. Every platform.','https://expo.dev/'],['Firebase','The power behind your app','https://firebase.google.com/'],['GitHub','A home for your code','https://github.com/']].map(([name,desc,url])=>`<a class="tool-row" href="${url}" target="_blank" rel="noopener noreferrer">${toolLogo(name)}<span><strong>${name}</strong><small>${desc}</small></span>${icon('arrowUpRight')}</a>`).join('')}</section>`;
function hero(){return `<section class="hero"><div class="hero-content"><span class="hero-kicker"><span class="green-dot"></span>YOUR IDEA STARTS HERE</span><h2>Big ideas. Real apps.<br>Built by <span>you.</span></h2><p>Go from “what if” to your first working app.<br>One prompt, one step, one little win at a time.</p><a class="button primary" href="#curriculum">${state.done.length===12?'View your completed class':state.started?'Continue to Step '+(currentStep()+1):'Start Step 1'} ${icon('arrowRight')}</a><div class="hero-meta"><span>${icon('code')} No experience needed</span><span class="meta-dot">·</span><span>About 4 hours · go at your pace</span></div></div><div class="hero-art" aria-hidden="true"><div class="art-orbit orbit-one"></div><div class="art-orbit orbit-two"></div><span class="art-spark spark-one">✦</span><span class="art-spark spark-two">✦</span><div class="float-badge built-badge"><span>✦</span> From idea to real life</div><div class="editor-illustration"><div class="editor-bar"><i></i><i></i><i></i><span>your-next-big-thing.tsx</span></div><div class="editor-body"><div class="line-numbers">1<br>2<br>3<br>4<br>5<br>6<br>7<br>8<br>9</div><div class="art-code"><span class="code-muted">// Something great starts here</span><br><span class="code-purple">const</span> <span class="code-blue">MyApp</span> = () =&gt; {<br>&nbsp; <span class="code-purple">return</span> (<br>&nbsp;&nbsp;&nbsp; <span class="code-green">&lt;YourBigIdea&gt;</span><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; <span class="code-peach">Hello, world.</span><br>&nbsp;&nbsp;&nbsp; <span class="code-green">&lt;/YourBigIdea&gt;</span><br>&nbsp; );<br>};<br><span class="code-muted">// Built by you. ♡</span></div></div><div class="editor-status"><span>◉ All systems ready</span><span>TypeScript</span></div></div><div class="phone-illustration"><div class="phone-island"></div><div class="phone-screen"><div class="phone-top"><span>9:41</span><span>▮▮▮ ▰</span></div><div class="phone-logo">hello<span>world.</span><b>✳</b></div><div class="phone-image"><span class="sun"></span><div class="mountain mountain-back"></div><div class="mountain mountain-front"></div><span class="image-caption">a little more<br>possibility.</span></div><div class="phone-interactions">♡ <span>⌁</span> <span>↗</span><b>♧</b></div><div class="phone-text-line"></div><div class="phone-text-line short"></div><div class="phone-nav">⌂ <span>⌕</span><b>+</b><span>♡</span><i></i></div></div></div><div class="float-badge live-badge"><span class="live-check">${icon('check')}</span><span>It’s alive!<small>Your first app is just steps away.</small></span></div></div></section>`;}
function progressCard(){return `<section class="card progress-card"><div class="section-title"><h2>Your learning journey</h2><span class="small-tag">${state.done.length===12?'Class complete':state.done.length?'Step '+(currentStep()+1)+' of 4':'Ready to start'}</span></div><div class="progress-ring" style="--progress:${percent()}%"><div><strong>${percent()}<span>%</span></strong><small>course complete</small></div></div><div class="progress-caption"><strong>${state.done.length} of 12 lessons</strong> completed</div><div class="mini-milestones">${modules.map(m=>`<div class="mini-milestone ${m.lessons.every(id=>state.done.includes(id))?'done':''}" title="${m.title}">${icon(m.lessons.every(id=>state.done.includes(id))?'check':m.icon)}</div>`).join('<span></span>')}</div><p class="progress-message">${state.done.length===12?'You made it. Look at what you built.':state.done.length? 'Step '+(currentStep()+1)+' is next: '+modules[currentStep()].title+'.':'Start with Step 1. You can do this in one sitting or take breaks.'}</p>${state.done.length===12?`<button class="button secondary full-width" data-action="certificate">${icon('trophy')} View your achievement</button>`:''}</section>`;}
function moduleList(){return `<div class="module-list">${modules.map((m,i)=>{const done=m.lessons.filter(id=>state.done.includes(id)).length;const active=i===currentStep(),complete=done===m.lessons.length;const visible=filter==='all'||(filter==='completed'?complete:filter==='up_next'?active:!complete);if(!visible)return '';return `<details class="module-card ${active?'is-current':''} ${complete?'is-complete':''}" ${page==='curriculum'&&active?'open':''}><summary><span class="module-icon ${m.color}">${icon(m.icon)}</span><span class="module-info"><span class="module-overline">STEP ${String(i+1).padStart(2,'0')} <span class="complete-label">${complete?'COMPLETE':active?done?'IN PROGRESS':'UP NEXT':'COMING UP'}</span></span><strong>${m.title}</strong><span class="module-description">${m.description}</span><span class="module-meta">${m.lessons.length} lessons <i>·</i> ${m.lessons.reduce((s,id)=>s+lessons[id-1].time,0)} min</span></span><span class="module-end"><span class="module-progress">${done}/${m.lessons.length}</span><span class="module-chevron">${icon('chevron')}</span></span></summary><div class="lesson-list">${m.lessons.map(id=>{const l=lessons[id-1];return `<button class="lesson-row" data-lesson="${id}"><span class="lesson-status ${state.done.includes(id)?'finished':''}">${state.done.includes(id)?icon('check'):String(id).padStart(2,'0')}</span><span>${l.title}<small>${l.tag}</small></span><span class="lesson-time">${l.time} min</span>${icon('chevron')}</button>`;}).join('')}</div></details>`;}).join('')||'<div class="empty-state">'+icon('flag')+'<h3>Your milestones are waiting</h3><p>Complete a module to see it here.</p><button class="button secondary" data-filter="all">See all modules</button></div>'}</div>`;}
function curriculumBlock(){return `<section class="curriculum-section"><div class="section-title curriculum-title"><div><h2>Your path from idea to app <span class="count-tag">4 steps</span></h2><p>A clear path. Real skills. Something you can call your own.</p></div>${page==='overview'?'<a class="text-link" href="#curriculum">View all '+icon('arrowRight')+'</a>':''}</div><div class="filter-tabs" aria-label="Filter course steps">${[['all','All 4 steps'],['up_next','Next step'],['completed','Completed']].map(([id,name])=>`<button data-filter="${id}" class="${filter===id?'active':''}" aria-pressed="${filter===id}">${name}${id==='all'?'<span>4</span>':''}</button>`).join('')}<span class="curriculum-estimate">${icon('clock')} At your own pace</span></div>${moduleList()}</section>`;}
function overview(){return `${pageHead('A LITTLE CURIOSITY GOES A LONG WAY',state.name?`Welcome back, ${escape(state.name.split(' ')[0])} <span class="wave">✳</span>`:'Hey, future builder <span class="wave">✳</span>','Your next big thing starts with one small step.')}<div class="dashboard-grid"><div class="main-column">${hero()}<div class="course-stats"><div><span class="stat-icon orange">${icon('book')}</span><span><strong>12 hands-on lessons</strong><small>Four clear steps</small></span></div><div><span class="stat-icon purple">${icon('clock')}</span><span><strong>About 4 hours</strong><small>One sitting or take breaks</small></span></div><div><span class="stat-icon green">${icon('rocket')}</span><span><strong>1 app. Built by you.</strong><small>From the first line to launch</small></span></div></div>${curriculumBlock()}</div><aside class="right-column">${progressCard()}${toolkit()}<section class="tip-card"><span class="tip-label">${icon('sparkles')} A LITTLE BUILDER WISDOM</span><blockquote>“You don’t have to see the whole staircase. Just take the first step.”</blockquote><p>Start small. Stay curious. Keep building.</p></section><a class="worksheet-link" href="assets/code-class-worksheet.pdf" download>${icon('download')} Original class worksheet ${icon('arrowUpRight')}</a></aside></div>`;}
function curriculum(){const step=currentStep(),next=nextLesson();return `${pageHead('ONE CLASS · FOUR CLEAR STEPS','Your path to a finished app','About 4 hours in total. Settle in and finish today, or take a break between steps.')}<section class="course-lead"><div class="course-lead-top"><div><span class="eyebrow">${state.done.length===12?'ALL DONE':'STEP '+String(step+1).padStart(2,'0')+' OF 04'}</span><h2>${state.done.length===12?'You completed the class!':'Start with Step '+(step+1)+': '+modules[step].title}</h2><p>${state.done.length===12?'Your app is ready. Take a moment to celebrate what you built.':'Next lesson: '+next.title+' · '+next.time+' min'}</p></div><a class="button primary" href="#" ${state.done.length===12?'data-action="certificate"':'data-lesson="'+next.id+'"'}>${state.done.length===12?'View your achievement':state.done.length?'Continue Step '+(step+1):'Begin Step 1'} ${icon('arrowRight')}</a></div><div class="step-track">${modules.map((m,i)=>`<span class="step-track-item ${m.lessons.every(id=>state.done.includes(id))?'complete':i===step?'active':''}"><b>${m.lessons.every(id=>state.done.includes(id))?'✓':i+1}</b> ${m.title}</span>`).join('')}</div></section><div class="classroom-layout"><div>${curriculumBlock()}</div><aside>${progressCard()}<div class="classroom-note">${icon('shield')}<p>Your notes and progress are saved to your account, so you can pick up on any device. Export your notes to keep a personal backup.</p></div></aside></div>`;}
function lessonSnippets(lesson) {
  const snippets = [];
  if (lesson.prompt) snippets.push({type:'prompt', title:lesson.title, text:lesson.prompt});
  for (const [part, prompt] of (lesson.extraPrompts || []).entries()) snippets.push({type:'extra', part, title:prompt.title, text:prompt.text});
  if (lesson.command) lesson.command.split('\n\n').forEach((text, part) => snippets.push({type:'command', part, title:lesson.id === 12 ? (part === 0 ? 'Build for iOS' : 'Build for Android') : lesson.title, text}));
  return snippets;
}
function copyAttributes(id, snippet) {
  return `data-copy-lesson="${id}" data-copy-type="${snippet.type}"${snippet.part === undefined ? '' : ` data-copy-part="${snippet.part}"`}`;
}
function prompts(){
  const entries = lessons.flatMap(lesson => lessonSnippets(lesson).map(snippet => ({lesson, snippet})));
  return `${pageHead('A LITTLE DIRECTION. A LOT OF POSSIBILITY.','Your prompt & command library','Every lesson’s AI prompts and terminal commands, together in one place.')}
    <div class="library-howto">${icon('help')}<p><strong>Prompts go in Cursor chat. Commands go in the terminal.</strong> Open the matching lesson for setup and testing instructions.</p><a href="#start">How it works ${icon('arrowRight')}</a></div>
    <label class="content-search">${icon('search')}<input id="prompt-search" placeholder="Find a prompt or command..." aria-label="Search prompts"></label>
    <div class="prompt-grid">${entries.map(({lesson:l,snippet:n})=>`<article class="card prompt-card" data-prompt-search="${escape((n.title+' '+l.title+' '+l.tag+' '+n.type+' '+n.text).toLowerCase())}"><span class="eyebrow">LESSON ${String(l.id).padStart(2,'0')} <span class="tag">${n.type==='command'?'TERMINAL':'AI PROMPT'}</span></span><h2>${escape(n.title)}</h2><p>${n.type==='command'?'Run in your app project’s terminal. Follow the lesson instructions before running this command.':l.intro}</p><pre>${escape(n.text)}</pre><div class="prompt-card-footer"><button class="text-link" data-lesson="${l.id}">Open lesson ${icon('arrowRight')}</button><button class="button secondary small" ${copyAttributes(l.id,n)}>${icon('copy')} Copy ${n.type==='command'?'command':'prompt'}</button></div></article>`).join('')}</div>
    <div class="empty-state hidden" id="prompt-empty">${icon('search')}<h3>No matching prompts</h3><p>Try a topic like Firebase, design, or Expo.</p></div>`;
}
function startBanner(){return `<a class="start-banner" href="#start"><span class="start-banner-icon">${icon('flag')}</span><span><strong>Start here. Finish with something you built.</strong><small>What you need, how each lesson works, and how to complete the class.</small></span><span class="start-banner-link">Read the guide ${icon('arrowRight')}</span></a>`;}
function startGuide(){
  const completed = state.done.length === lessons.length;
  return `${pageHead('YOUR FIRST STEP, MADE SIMPLE','How to start. How to finish.','A practical guide to working through Code Class, from setup to your final build.')}
    <section class="guide-intro"><div><span class="hero-kicker"><span class="green-dot"></span>4 STEPS · 12 SHORT LESSONS</span><h2>Keep this class open.<br>Build your app alongside it.</h2><p>Read the instructions here, then do the work in your own Cursor project. This website holds your lessons, prompts, notes, and progress. Your app runs in your browser and on your phone.</p><div class="guide-actions"><a class="button primary" href="#curriculum">Start with Step 1 ${icon('arrowRight')}</a><a class="button secondary" href="#curriculum">See the 4 steps ${icon('book')}</a></div></div><div class="guide-status"><span class="guide-status-icon">${icon(completed?'trophy':'flag')}</span><strong>${state.done.length}<span> / 12</span></strong><p>lessons completed</p><span class="guide-progress-track"><span style="width:${percent()}%"></span></span>${completed?'<button class="text-link" data-action="certificate">View your achievement '+icon('arrowRight')+'</button>':`<a class="text-link" href="#curriculum">${state.started?'Continue with':'Next up:'} Step ${currentStep()+1} ${icon('arrowRight')}</a>`}</div></section>
    <div class="guide-layout"><div class="guide-main">
      <section class="card guide-section"><div class="guide-section-heading"><span>01</span><div><h2>Get your workspace ready</h2><p>You can do all of this in lesson 1.</p></div></div><ul class="guide-checklist"><li>${icon('check')}<span><strong>A computer and a phone</strong>Build on your computer, then test on an iOS or Android device. Keep this class and Cursor open side by side.</span></li><li>${icon('check')}<span><strong>Cursor, Node.js LTS, and Expo Go</strong>Install Cursor and Node.js on your computer, and Expo Go on your phone. Lesson 1 includes the download links.</span></li><li>${icon('check')}<span><strong>Your own accounts</strong>Set up GitHub and Expo to start. You’ll create your own Firebase project in module 3.</span></li><li>${icon('check')}<span><strong>One app idea and a project folder</strong>Choose a small idea, create a folder, and open it in Cursor. The class uses a photo-sharing app as its example.</span></li></ul><div class="guide-inline-actions"><a class="text-link" href="#curriculum">Go to Step 1 ${icon('arrowRight')}</a><button class="text-link" data-action="project">Name your project ${icon('layers')}</button></div></section>
      <section class="card guide-section"><div class="guide-section-heading"><span>02</span><div><h2>Use the right place for each instruction</h2><p>The two copy buttons do different jobs.</p></div></div><div class="guide-instruction-grid"><article><span class="guide-instruction-label">${icon('sparkles')} AI PROMPT</span><h3>Paste into Cursor chat</h3><p>Click <strong>Copy prompt</strong>. Replace placeholders like <code>[your-folder-name]</code>, attach any requested design reference, and send it in Cursor’s AI chat. Review the proposed changes and test the result.</p></article><article><span class="guide-instruction-label">${icon('terminal')} TERMINAL COMMAND</span><h3>Run in your app’s terminal</h3><p>Open a terminal in Cursor with your app folder as its working directory. Use <strong>Copy command</strong>, paste the command, and press Enter. For a sequence, run one line at a time and wait for it to finish.</p></article></div><div class="guide-note">${icon('help')}<p>A development server such as <code>npm start</code> keeps running while you preview the app. Use a second terminal for other commands, or press <code>Ctrl+C</code> to stop the server. In the final lesson, choose the build command for the platform you want to test.</p></div><a class="text-link" href="#prompts">Browse every prompt and command ${icon('arrowRight')}</a></section>
      <section class="card guide-section"><div class="guide-section-heading"><span>03</span><div><h2>Work through one lesson at a time</h2><p>Read → build → test → complete. Repeat.</p></div></div><ol class="guide-workflow"><li><strong>Open a lesson in The 4 steps.</strong><p>Expand a module and choose a lesson. Start at lesson 1 and follow the sequence; earlier lessons prepare what you need later.</p></li><li><strong>Follow the steps in your own project.</strong><p>Use the prompts, commands, and resource links in the lesson. Check that your app behaves as described before moving on.</p></li><li><strong>Complete “Before you move on”.</strong><p>Tick each item only after you’ve done and verified it. The <strong>Complete lesson</strong> button becomes available when every box is checked.</p></li><li><strong>Save a note, then continue.</strong><p>Write down questions or useful links. Click <strong>Complete lesson</strong> to update your progress and open the next lesson. You can revisit any lesson whenever you need to.</p></li></ol></section>
      <section class="card guide-section guide-finish"><div class="guide-section-heading"><span>04</span><div><h2>Finish the class with a tested app</h2><p>The final milestone brings the whole project together.</p></div></div><ul class="guide-checklist"><li>${icon('check')}<span>Your app’s sign-in, profiles, posts, comments, likes, and messages work and retain their data.</span></li><li>${icon('check')}<span>You’ve created a build for your chosen platform and tested it on a device.</span></li><li>${icon('check')}<span>Your code is committed and backed up on GitHub, and your build link is saved in your notes.</span></li><li>${icon('check')}<span>All 12 lessons are marked complete, including the final lesson’s checklist.</span></li></ul><p>When all lessons are complete, your progress reaches 100% and your achievement unlocks. Add your name in your profile, then use <strong>View your achievement</strong> to print it or save it as a PDF from the print dialog.</p><div class="guide-note">${icon('flag')}<p>Completion is based on the checklists you confirm. This classroom doesn’t inspect your external app. Store submission and approval are separate from completing the class.</p></div><div class="guide-actions">${completed?'<button class="button primary" data-action="certificate">View your achievement '+icon('trophy')+'</button>':`<a class="button primary" href="#curriculum">${state.started?'Continue to Step '+(currentStep()+1):'Start Step 1'} ${icon('arrowRight')}</a>`}<a class="button secondary" href="#notes">Open my notes ${icon('note')}</a></div></section>
    </div><aside class="guide-aside"><section class="card guide-roadmap"><h2>Your four milestones</h2>${modules.map((m,i)=>`<a href="#curriculum" class="guide-module"><span class="module-icon ${m.color}">${icon(m.icon)}</span><span><small>STEP ${i+1} · LESSONS ${m.lessons[0]}–${m.lessons.at(-1)}</small><strong>${m.title}</strong><em>${['Get your first app running in a browser.','Design, test, and save your interface.','Connect real accounts and saved data.','Create and test a mobile build.'][i]}</em></span>${icon('chevron')}</a>`).join('')}</section><section class="card guide-side-note">${icon('note')}<h2>Pick up where you left off</h2><p>Notes, checklist ticks, and completed lessons save automatically to your account. Sign in on any device and choose <strong>Continue learning</strong> to open the first unfinished lesson.</p><p>Use <strong>My notes → Export notes</strong> to download a copy of your writing.</p><a class="text-link" href="#notes">Go to my notes ${icon('arrowRight')}</a></section><section class="guide-side-note guide-stuck">${icon('help')}<h2>Something not working?</h2><p>Copy the exact error into Cursor chat. Explain what you tried, what happened, and what you expected. Apply one fix at a time, then test again.</p><a class="text-link" href="#resources">Find your resources ${icon('arrowRight')}</a></section></aside></div>`;
}
function notesPage(){return `${pageHead('KEEP THE LITTLE LIGHTBULB MOMENTS','A home for your thoughts.','Ideas, breakthroughs, and things to try next. Saved as you type.',`<button class="button secondary" data-action="export-notes">${icon('download')} Export notes</button>`)}<div class="notes-layout"><section class="card project-notes"><div class="section-title"><h2>${icon('note')} Project notebook</h2><span class="autosave-label">${student?'Saved to your account':'Sign up to save'}</span></div><textarea id="project-notes" aria-label="Project notes" placeholder="What are you building? Jot down your idea, helpful links, next steps, or your first little win...">${escape(state.notes.project||'')}</textarea><div class="notes-footer">Your space to think out loud.<span id="note-count">${(state.notes.project||'').length} characters</span></div></section><aside class="card lesson-notes"><h2>Lesson notes</h2><p>Pick a lesson to keep your thoughts close to what you’re learning.</p>${lessons.map(l=>`<button data-lesson="${l.id}" class="note-lesson"><span>${String(l.id).padStart(2,'0')}</span><span>${l.title}${state.notes[l.id]?'<small>Note saved</small>':''}</span>${icon('chevron')}</button>`).join('')}</aside></div>`;}
function resources(){return `${pageHead('GOOD TOOLS. GREAT POSSIBILITIES.','Your builder’s bookshelf.','Everything you need to keep learning, creating, and moving forward.')}<div class="resource-grid">${toolkit()}<section class="card resource-feature"><span class="resource-art orange">${icon('book')}</span><span class="eyebrow">THE ORIGINAL GUIDE</span><h2>The Code Class<br>prompt sheet</h2><p>Keep the original five-page class worksheet close by. The online lessons expand it with checklists, notes, and updated setup guidance.</p><a class="button primary" href="assets/code-class-worksheet.pdf" download>${icon('download')} Download worksheet</a></section><section class="card docs-card"><h2>Go a little deeper</h2>${[['Expo project setup','Create and run your first project','https://docs.expo.dev/get-started/create-a-project/'],['Firebase security rules','Give the right people the right access','https://firebase.google.com/docs/rules/basics'],['Firebase billing','Understand usage and budget alerts','https://firebase.google.com/docs/projects/billing/avoid-surprise-bills'],['EAS Build','Prepare your native mobile builds','https://docs.expo.dev/build/setup/'],['GitHub fundamentals','Save, track, and share your code','https://docs.github.com/en/get-started']].map(([t,d,u])=>`<a class="doc-link" href="${u}" target="_blank" rel="noopener noreferrer"><span><strong>${t}</strong><small>${d}</small></span>${icon('arrowUpRight')}</a>`).join('')}</section></div>`;}
function render(){page=location.hash.slice(1)||'overview';if(!['overview','start','curriculum','prompts','notes','resources'].includes(page))page='overview';const titles={start:'How it works',overview:'Overview',curriculum:'The 4 steps',prompts:'Prompt library',notes:'My notes',resources:'Resources'};document.title=`${titles[page]} — Code Class`;$('#breadcrumb-title').textContent=titles[page];document.querySelectorAll('[data-nav]').forEach(a=>{a.classList.toggle('active',a.dataset.nav===page);if(a.dataset.nav===page)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});$('#main').innerHTML=({overview,start:startGuide,curriculum,prompts,notes:notesPage,resources}[page])();profileUI();document.body.classList.remove('nav-open');$('[data-action=menu]').setAttribute('aria-expanded','false');hydrate();}
function modalShell(title,content,cls=''){const dialog=$('#modal');dialog.className=cls;if(dialog.contains($('#toast')))document.body.append($('#toast'));dialog.innerHTML=`<div class="modal-top"><a class="modal-brand" href="#overview" data-action="close"><img class="modal-brand-photo" src="assets/brand-portrait.png" alt=""> <span>codeclass.</span></a><button class="icon-button" data-action="close" aria-label="Close dialog">${icon('close')}</button></div>${content}`;if(!dialog.open)dialog.showModal();const heading=$('#modal-title');if(heading){heading.tabIndex=-1;heading.focus({preventScroll:true});}dialog.scrollTop=0;}
function openLesson(id){const lesson=lessons.find(l=>l.id===Number(id));if(!lesson)return;state.last=lesson.id;state.started=true;save();const mi=modules.findIndex(m=>m.lessons.includes(lesson.id));const checked=state.checks[id]||[];modalShell(lesson.title,`<div class="lesson-heading"><span class="eyebrow">STEP ${String(mi+1).padStart(2,'0')} OF 04 · ${modules[mi].title.toUpperCase()}</span><div class="lesson-heading-meta"><span>LESSON ${String(id).padStart(2,'0')} OF 12 · STEP ${String(mi+1).padStart(2,'0')} OF 04</span><span>${icon('clock')} ${lesson.time} min</span></div><h1 id="modal-title">${lesson.title}</h1><p>${lesson.intro}</p></div><div class="lesson-body"><div class="lesson-steps">${lesson.steps.map(([t,d],i)=>`<section class="lesson-step"><span>${i+1}</span><div><h2>${t}</h2><p>${d}</p></div></section>`).join('')}</div>${lessonSnippets(lesson).map(n=>`<section class="lesson-code ${n.type==='command'?'terminal-code':''}"><div>${icon(n.type==='command'?'terminal':'sparkles')} ${n.type==='command'?(lesson.id===12?n.title.toUpperCase():'IN YOUR TERMINAL'):(n.type==='extra'?escape(n.title.toUpperCase()):'YOUR CURSOR PROMPT')}<button ${copyAttributes(id,n)}>${icon('copy')} Copy ${n.type==='command'?'command':'prompt'}</button></div><pre>${escape(n.text)}</pre></section>`).join('')}<div class="lesson-tip">${icon('sparkles')}<p><strong>A little help along the way</strong>${lesson.tip}</p></div><section class="lesson-checklist"><div class="section-title"><h2>Before you move on</h2><span id="check-count">${checked.filter(Boolean).length} / ${lesson.checks.length}</span></div><p>Try each step in your own project, then check it off.</p>${lesson.checks.map((t,i)=>`<label><input type="checkbox" data-check="${i}" data-lesson-id="${id}" ${checked[i]?'checked':''}><span>${escape(t)}</span></label>`).join('')}</section><section class="lesson-note-section"><label for="lesson-note">${icon('note')} Your lesson notes <span>Saved as you type</span></label><textarea id="lesson-note" data-note-lesson="${id}" placeholder="A thought, a question, a little breakthrough...">${escape(state.notes[id]||'')}</textarea></section>${lesson.links.length?`<div class="lesson-links">${lesson.links.map(([t,u])=>`<a href="${u}" target="_blank" rel="noopener noreferrer">${t} ${icon('arrowUpRight')}</a>`).join('')}</div>`:''}</div><div class="lesson-bottom"><button class="button secondary" data-lesson="${id-1}" ${id===1?'disabled':''}>${icon('arrowLeft')} Previous</button><span id="completion-hint">${state.done.includes(Number(id))?'Lesson completed. Nicely done!':'Finish the checklist to complete this lesson.'}</span><button class="button primary" id="complete-lesson" data-complete="${id}" ${!lesson.checks.every((_,i)=>checked[i])?'disabled':''}>${state.done.includes(Number(id))?'Continue':Number(id)===12?'Finish course':'Complete lesson'} ${icon('arrowRight')}</button></div>`,'lesson-modal');}
function openProject(){modalShell('Your next big thing',`<form id="project-form" class="form-modal"><span class="eyebrow">YOUR OWN LITTLE CORNER OF POSSIBILITY</span><h1 id="modal-title">Your next big thing.</h1><p>Give your idea a name. You can figure out the rest as you go.</p><label>Project name<input name="project" maxlength="60" required value="${escape(state.project)}" placeholder="My first app"></label><label>What do you want to build?<textarea name="idea" maxlength="2000" placeholder="An app that helps people...">${escape(state.idea)}</textarea></label><div class="project-summary">${icon('layers')}<span>Built with Cursor, Expo & Firebase<br><small>Saved to your Code Class account.</small></span></div><button class="button primary full-width" type="submit">Save my project ${icon('check')}</button></form>`);}
function openProfile(){modalShell('Make yourself at home',`<form id="profile-form" class="form-modal"><span class="eyebrow">HEY THERE, BUILDER</span><h1 id="modal-title">Make yourself at home.</h1><p>What should we call you? This personalizes your workspace and course achievement.</p><label>Your name<input name="name" maxlength="60" required value="${escape(state.name)}" placeholder="Your name" autocomplete="name"></label>${roleField(student?.role)}<label>Email<input type="email" value="${escape(student?.email||'')}" readonly></label><p class="form-footnote">Your profile, notes, and progress are saved to your Code Class account.</p><button class="button primary full-width" type="submit">Save my profile ${icon('check')}</button><div class="auth-switch"><button type="button" class="text-link" data-action="sign-out">Sign out</button></div></form>`);}
const roleField=selected=>`<label>Role<select name="role" required><option value="" disabled ${selected?'':'selected'}>Choose your role</option>${ROLES.map(r=>`<option ${r===selected?'selected':''}>${r}</option>`).join('')}</select></label>`;
function openAuth(mode='signup'){
  const copy={signup:['CREATE YOUR FREE ACCOUNT','Let’s get you started.','Sign up to save your lessons, checklists, notes, and progress to your account.','Create my account'],signin:['WELCOME BACK','Sign in to keep building.','Pick up right where you left off, on any device.','Sign in'],complete:['ONE LAST STEP','Tell us a little about you.','Add your name and role to finish setting up your Code Class account.','Finish setup'],reset:['FORGOT YOUR PASSWORD?','Reset your password.','Enter your email and we’ll send you a link to choose a new password.','Send reset link']}[mode];
  const nameField=`<label>Your name<input name="name" maxlength="60" required value="${escape(authUser?.displayName||state.name)}" placeholder="Your name" autocomplete="name"></label>`;
  const emailField=`<label>Email<input name="email" type="email" required maxlength="254" placeholder="you@example.com" autocomplete="email"></label>`;
  const passwordField=`<label>Password<input name="password" type="password" required minlength="6" placeholder="At least 6 characters" autocomplete="${mode==='signup'?'new-password':'current-password'}"></label>`;
  const fields={signup:nameField+emailField+passwordField+roleField(),signin:emailField+passwordField,complete:nameField+roleField(),reset:emailField}[mode];
  const links={signup:'Already have an account? <button type="button" class="text-link" data-action="auth-signin">Sign in</button>',signin:'New here? <button type="button" class="text-link" data-action="auth-signup">Create an account</button><span class="meta-dot">·</span><button type="button" class="text-link" data-action="auth-reset">Forgot password?</button>',complete:'<button type="button" class="text-link" data-action="sign-out">Use a different account</button>',reset:'<button type="button" class="text-link" data-action="auth-signin">Back to sign in</button>'}[mode];
  modalShell(copy[1],`<form id="auth-form" class="form-modal" data-mode="${mode}"><span class="eyebrow">${copy[0]}</span><h1 id="modal-title">${copy[1]}</h1><p>${copy[2]}</p>${fields}<p class="auth-error" id="auth-error" role="alert" hidden></p><button class="button primary full-width" type="submit">${copy[3]} ${icon('arrowRight')}</button><div class="auth-switch">${links}</div></form>`);
}
function authMessage(err){return ({'auth/email-already-in-use':'That email already has an account. Sign in instead.','auth/invalid-email':'Enter a valid email address.','auth/weak-password':'Use a password with at least 6 characters.','auth/invalid-credential':'That email and password don’t match.','auth/wrong-password':'That email and password don’t match.','auth/user-not-found':'That email and password don’t match.','auth/missing-password':'Enter your password.','auth/too-many-requests':'Too many attempts. Please wait a moment and try again.','auth/network-request-failed':'You appear to be offline. Check your connection and try again.','auth/operation-not-allowed':'Email sign-up isn’t enabled for this class yet.','permission-denied':'Your account is ready, but we couldn’t save your profile. Please try again.'})[err?.code]||'Something went wrong. Please try again.';}
async function requireStudent(action){if(!authReady)await authReadyPromise;if(student){action();return;}pendingAction=action;openAuth(authUser?'complete':'signup');}
function finishAuth(message){const next=pendingAction;pendingAction=null;$('#modal').close();render();next?.();toast(message);}
async function submitAuth(form){
  const mode=form.dataset.mode,data=new FormData(form),button=form.querySelector('[type=submit]'),error=$('#auth-error');
  const name=String(data.get('name')||'').trim(),email=String(data.get('email')||'').trim(),password=String(data.get('password')||''),role=String(data.get('role')||'');
  if((mode==='signup'||mode==='complete')&&(!name||!ROLES.includes(role))){error.textContent='Add your name and choose a role.';error.hidden=false;return;}
  error.hidden=true;button.disabled=true;authFlow=true;
  try{
    if(mode==='reset'){await resetPassword(email);openAuth('signin');toast('Check your inbox for a password reset link.');return;}
    if(mode==='signup')authUser=await signUp({name,email,password});
    if(mode==='signin')authUser=await signIn(email,password);
    const existing=mode==='signin'?await loadStudent(authUser.uid):null;
    if(mode==='signin'&&!existing){openAuth('complete');return;}
    if(existing){applyRemote(existing);student={uid:authUser.uid,email:authUser.email,name:existing.name,role:existing.role};}
    else{state.name=name;writeLocal();await createStudent(authUser,{name,role},remoteData());student={uid:authUser.uid,email:authUser.email,name,role};}
    finishAuth(existing?`Welcome back${state.name?', '+state.name.split(' ')[0]:''}.`:'You’re all set. Let’s build something.');
  }catch(err){console.error(err);if(mode==='signup'&&authUser&&!String(err?.code).startsWith('auth/'))openAuth('complete');const target=$('#auth-error');target.textContent=authMessage(err);target.hidden=false;}
  finally{authFlow=false;button.disabled=false;}
}
async function signOutAndReset(){if(syncTimer)await syncNow();pendingAction=null;await signOutStudent().catch(err=>console.error(err));student=null;authUser=null;state=structuredClone(defaultState);try{localStorage.removeItem('codeclass-v1');}catch{}if($('#modal').open)$('#modal').close();render();toast('You’re signed out. See you soon.');}
function openHelp(){modalShell('A little help goes a long way',`<div class="form-modal help-modal"><span class="eyebrow">YOU DON’T HAVE TO FIGURE IT ALL OUT AT ONCE</span><h1 id="modal-title">A little help goes a long way.</h1><p>This class guides you through building an app in Cursor, Expo, and Firebase. Keep your project open beside your classroom.</p><a class="text-link" href="#start" data-action="close">Read the full start-to-finish guide ${icon('arrowRight')}</a><h2>How to work through a lesson</h2><ol><li>Read the steps and try them in your own project.</li><li>Copy a prompt, replace the placeholders, and send it to Cursor.</li><li>Test what you built, then tick the lesson checklist.</li><li>Save any thoughts in your notes and complete the lesson.</li></ol><h2>Stuck on an error?</h2><p>Copy the exact error into Cursor. Include what you were trying to do, what happened, and what you expected. Work through one fix at a time.</p><h2>Where is my progress saved?</h2><p>Your progress, checklists, and notes are saved to your Code Class account. Sign in on any device to pick up where you left off. Use “Export notes” in My notes to download your writing.</p><a class="button primary" href="#resources" data-action="close">Browse your resources ${icon('arrowRight')}</a></div>`);}
function openSearch(){modalShell('Find your next step',`<div class="search-modal-body"><h1 id="modal-title">Find your next step.</h1><label class="content-search">${icon('search')}<input id="global-search" autofocus placeholder="Try “Firebase”, “design”, or “Expo”" aria-label="Search lessons"></label><div id="search-results"></div><p class="search-footnote">12 lessons. A whole world of possibility.</p></div>`,'search-modal');searchResults('');$('#global-search').focus();}
function searchResults(query){const results=lessons.filter(l=>(l.title+' '+l.intro+' '+l.tag+' '+l.steps.flat().join(' ')).toLowerCase().includes(query.toLowerCase()));$('#search-results').innerHTML=results.length?results.map(l=>`<button class="search-result" data-lesson="${l.id}"><span class="search-result-icon">${icon(state.done.includes(l.id)?'check':'book')}</span><span><strong>${l.title}</strong><small>Lesson ${l.id} · ${l.time} min · ${l.tag}</small></span>${icon('arrowRight')}</button>`).join(''):`<div class="empty-state">${icon('search')}<h3>No lessons found</h3><p>Try a broader topic, like “app” or “project”.</p></div>`;}
function certificate(){if(state.done.length!==12)return;modalShell('You’re an app builder',`<div class="certificate"><div class="certificate-seal">${icon('trophy')}</div><span class="eyebrow">ONE IDEA. TWELVE LESSONS. A NEW BEGINNING.</span><h1 id="modal-title">You’re an app builder.</h1><p>This celebrates</p><h2>${escape(state.name||'A curious, determined builder')}</h2><p>for completing all 12 lessons of Code Class<br>and taking an idea from the first prompt to a working app.</p><strong class="certificate-project">${escape(state.project)}</strong><p class="certificate-date">Completed ${escape(new Date(state.completedAt||Date.now()).toLocaleDateString(undefined,{year:'numeric',month:'long',day:'numeric'}))}</p><button class="button primary" data-action="print">${icon('download')} Save or print achievement</button><small>A personal course milestone, based on your completed checklists.</small></div>`,'certificate-modal');}
async function copyLesson(id,type,part){
  const lesson=lessons[Number(id)-1];
  const snippet=lessonSnippets(lesson).find(n=>n.type===type && (part===undefined?n.part===undefined:n.part===Number(part)));
  if(!snippet)return;
  try{await navigator.clipboard.writeText(snippet.text);toast(`${type==='command'?'Command':'Prompt'} copied. ${type==='command'?'Run it in your app’s terminal.':'Paste it into Cursor chat.'}`);}
  catch{modalShell('Copy this text',`<div class="form-modal"><h1 id="modal-title">Copy this text</h1><p>Select and copy the text below.</p><textarea id="copy-fallback" rows="9">${escape(snippet.text)}</textarea></div>`);$('#copy-fallback').select();}
}
function exportNotes(){const content=`# Code Class — ${state.project}\n\nBuilder: ${state.name||'You'}\nProgress: ${state.done.length}/12 lessons\nProject idea: ${state.idea}\n\n## Project notebook\n${state.notes.project||'No project notes yet.'}\n\n`+lessons.map(l=>`## Lesson ${l.id}: ${l.title}${state.done.includes(l.id)?' (completed)':''}\n${state.notes[l.id]||'No notes yet.'}`).join('\n\n');const url=URL.createObjectURL(new Blob([content],{type:'text/markdown;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='code-class-notes.md';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Your notes are ready to keep.');}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action],[data-lesson],[data-filter],[data-copy-lesson],[data-complete]');if(!b)return;if(b.dataset.lesson){const id=Number(b.dataset.lesson);requireStudent(()=>openLesson(id));return;}if(b.dataset.filter){filter=b.dataset.filter;render();return;}if(b.dataset.copyLesson){const {copyLesson:id,copyType:type,copyPart:part}=b.dataset;requireStudent(()=>copyLesson(id,type,part));return;}if(b.dataset.complete){const id=Number(b.dataset.complete),l=lessons[id-1];if(!l.checks.every((_,i)=>state.checks[id]?.[i]))return;const isNew=!state.done.includes(id);if(isNew)state.done.push(id);if(state.done.length===12&&!state.completedAt)state.completedAt=new Date().toISOString();save();render();if(state.done.length===12&&isNew)certificate();else if(id<12){const nextStep=modules.findIndex(m=>m.lessons.includes(id+1));openLesson(id+1);toast(isNew?'Lesson marked complete. '+(nextStep!==modules.findIndex(m=>m.lessons.includes(id))?'Step '+(nextStep+1)+' is next!':'Next lesson is ready.'):'Let’s keep building.');}else{$('#modal').close();toast('Lesson complete! Finish any remaining lessons to complete the course.');}return;}const actions={project:openProject,profile:openProfile,help:openHelp,search:openSearch,close:()=>$('#modal').close(),menu:()=>{const open=document.body.classList.toggle('nav-open');$('[data-action=menu]').setAttribute('aria-expanded',String(open));},'export-notes':exportNotes,certificate,print:()=>window.print(),'auth-signup':()=>openAuth('signup'),'auth-signin':()=>openAuth('signin'),'auth-reset':()=>openAuth('reset'),'sign-out':signOutAndReset};const run=actions[b.dataset.action];if(!run)return;if(['project','profile','certificate','export-notes'].includes(b.dataset.action))requireStudent(run);else run();});
document.addEventListener('focusin',e=>{if(e.target.id==='project-notes'&&!student){e.target.blur();requireStudent(()=>{});}});
document.addEventListener('input',e=>{const t=e.target;if(t.id==='global-search')searchResults(t.value);if(t.id==='prompt-search'){let count=0;document.querySelectorAll('[data-prompt-search]').forEach(c=>{const match=c.dataset.promptSearch.includes(t.value.toLowerCase().trim());c.hidden=!match;if(match)count++;});$('#prompt-empty').classList.toggle('hidden',count>0);}if(t.id==='project-notes'){state.notes.project=t.value;save();$('#note-count').textContent=`${t.value.length} characters`;}if(t.dataset.noteLesson){state.notes[t.dataset.noteLesson]=t.value;save();}});
document.addEventListener('change',e=>{const t=e.target;if(t.dataset.check!==undefined){const id=t.dataset.lessonId;state.checks[id]||=[];state.checks[id][Number(t.dataset.check)]=t.checked;const complete=lessons[id-1].checks.every((_,i)=>state.checks[id][i]);if(!complete&&state.done.includes(Number(id))){state.done=state.done.filter(d=>d!==Number(id));delete state.completedAt;render();}save();$('#check-count').textContent=`${state.checks[id].filter(Boolean).length} / ${lessons[id-1].checks.length}`;$('#complete-lesson').disabled=!complete;$('#completion-hint').textContent=complete?'Ready for your next little win.':'Finish the checklist to complete this lesson.';}});
document.addEventListener('submit',e=>{if(e.target.id==='auth-form'){e.preventDefault();submitAuth(e.target);return;}if(!['project-form','profile-form'].includes(e.target.id))return;e.preventDefault();const data=new FormData(e.target);if(e.target.id==='project-form'){state.project=String(data.get('project')).trim()||'My first app';state.idea=String(data.get('idea')).trim();}else{state.name=String(data.get('name')).trim();const role=String(data.get('role')||'');if(student){student.name=state.name;if(ROLES.includes(role))student.role=role;}}save();$('#modal').close();render();toast('Saved. Make yourself at home.');});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
$('#modal').addEventListener('close',()=>{if($('#modal').contains($('#toast')))document.body.append($('#toast'));if(page==='notes')render();});
$('.skip-link').addEventListener('click',e=>{e.preventDefault();$('#main').focus();$('#main').scrollIntoView();});
function closeMenu(){document.body.classList.remove('nav-open');$('[data-action=menu]').setAttribute('aria-expanded','false');}
$('#mobile-scrim').addEventListener('click',closeMenu);
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openSearch();}if(e.key==='Escape')closeMenu();});
window.addEventListener('hashchange',()=>{filter='all';render();window.scrollTo({top:0});});
window.addEventListener('pagehide',()=>{if(syncTimer)syncNow();});
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden'&&syncTimer)syncNow();});
watchAuth(async user=>{
  authUser=user;
  if(!user){student=null;}
  else if(!authFlow&&student?.uid!==user.uid){try{const data=await loadStudent(user.uid);if(data){applyRemote(data);student={uid:user.uid,email:user.email,name:data.name,role:data.role};}else student=null;}catch(err){console.error(err);toast('We couldn’t load your saved progress. Please refresh and try again.');}}
  if(!authReady){authReady=true;resolveAuthReady();}
  if(!authFlow)render();
});
render();
